                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            objects.append((color, set(cells)))

    positions = [cells.copy() for _, cells in objects]
    # Process nearest-to-boundary objects first, allowing later objects to rest on them.
    order = sorted(range(len(objects)), key=lambda i: min(abs(r-boundary) for r, _ in positions[i]))
    for i in order:
